const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Point(50.332360, -116.939238).buffer(60000);
    const date1 = '2020-12-02';
    const date2 = '2020-12-05';
    const collectionName = 'MODIS/061/MOD09GA'; // Daily Terra surface reflectance

    // Function to calculate cloud cover percentage from MODIS State QA band
    const calculateCloudCover = (date, geometry) => {
        const imageCollection = ee.ImageCollection(collectionName)
            .filterDate(date)
            .filterBounds(geometry);

        // Return null if no images are found
        if (imageCollection.size().getInfo() === 0) {
            return null;
        }

        const image = imageCollection.first();
        const qaBand = image.select('state_1km');
        // Bit 0: Cloud State (0 = clear, 1 = cloudy)
        // Extract this bit to create a cloud mask
        const cloudMask = qaBand.bitwiseAnd(1).eq(1);

        const stats = cloudMask.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e9
        });

        // The mean of a binary mask is the percentage of '1's
        const cloudCover = ee.Number(stats.get('state_1km_mean'));
        const pixelCount = ee.Number(stats.get('state_1km_count'));
        return {
            cover: cloudCover,
            pixels: pixelCount
        };
    };

    // 2. Data Acquisition & Processing
    const result1 = calculateCloudCover(date1, region);
    const result2 = calculateCloudCover(date2, region);

    // 3. Validation and Evidence
    if (!result1 || !result2) {
        console.log(`Image collection for 2020-12-02: ${result1 ? 'Found' : 'Not Found'}`);
        console.log(`Image collection for 2020-12-05: ${result2 ? 'Found' : 'Not Found'}`);
        console.log('C1: Empty Collection (No images found for one or both dates).');
        console.log('A');
        return;
    }

    const cover1 = result1.cover.getInfo();
    const pixels1 = result1.pixels.getInfo();
    const cover2 = result2.cover.getInfo();
    const pixels2 = result2.pixels.getInfo();

    if (pixels1 === 0 || pixels2 === 0) {
        console.log(`Valid pixels on ${date1}: ${pixels1}`);
        console.log(`Valid pixels on ${date2}: ${pixels2}`);
        console.log('C2: No Valid Pixels (Images exist, but 0 pixels in region).');
        console.log('A');
        return;
    }

    if (cover1 === null || cover2 === null) {
        console.log(`Cloud cover calculation for ${date1}: ${cover1}`);
        console.log(`Cloud cover calculation for ${date2}: ${cover2}`);
        console.log('C3: Calculation Failure (Result is Null or NaN).');
        console.log('A');
        return;
    }

    const coverPercent1 = cover1 * 100;
    const coverPercent2 = cover2 * 100;

    console.log(`Cloud Cover on ${date1}: ${coverPercent1.toFixed(2)}% (Pixels: ${pixels1})`);
    console.log(`Cloud Cover on ${date2}: ${coverPercent2.toFixed(2)}% (Pixels: ${pixels2})`);

    // 4. Final Answer
    if (coverPercent2 > coverPercent1) {
        console.log('Conclusion: Cloud cover increased.');
        console.log('A');
    } else {
        console.log('Conclusion: Cloud cover did not increase.');
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log('D');
});
